import io
p = "experiments/E291_sd-road-level-lane-counts/experiment.md"
s = io.open(p, encoding="utf-8", newline="").read()


def rep(a, b, cnt=1):
    global s
    assert s.count(a) == cnt, (a[:70], s.count(a))
    s = s.replace(a, b)


rep("Version 3 of 2026-11-15 10:50 after", "Version 4 of 2026-11-15 11:25 (version 3 of 10:50 answered the first critic pass; the delta check of version 3 was REVISE with four blocking points, all taken here: the rule mapped 'not shown' to 'fails' and the card's own prediction returned HARMFUL, the control was ambiguous, no clause carried the count attribution, the 6 m presence gate drops 13 % of the true ends) after")
rep("(5) the SHUFFLED-table read-out gains more than 0.003 over the control", "(5) the lower end of the 95 % interval of (the SHUFFLED-table read-out of b minus the twin) is above 0")
i = s.index("**The JSON `rule` carries the headline gain clause only")
j = s.index("## 1. The input (what is in it")
rule = """**The JSON `rule` carries the headline gain clause only; the tokens come from the prose below and `decide.py` is NOT used (`by hand: replay`): the noise read-outs are not arms of the card.** **The rule in words (written before the run).** **Control = the recipe TWIN** (E291.c_s<S>: the same staged code, environment and data order with the prior flag off) for G, R and the shuffled kill; the stored E312 is reported beside it, and if |twin - stored| exceeds 0.005 snapped topo F1 on either seed the card says so and decides against the twin. VAL 873 frames, 22 scenes; the interval is a paired scene bootstrap, 1000 resamples, drawing the scene list ONCE per resample and using it for both seeds, of the MEAN over the two seeds of the snapped topo F1 difference (`jdiag.py` is not frozen: a `boot_pooled` function is added; it covers scene sampling only, not retraining noise, which the twin-against-stored gap shows). **Why three-valued (delta critic B1):** two seeds of the SAME recipe differ by 0.0040 and a single pair's 95 % scene interval is [-0.0077, +0.0164] (half-width about 0.012 on 22 scenes; pooled over two seeds about 0.009, to be measured): a gain of +0.008 cannot show as an interval that excludes 0, so "not shown" must not read as "fails". **(G) gain with a clean map, arm b read with the CLEAN table:** **G+** when the pooled point is at least +0.01, the interval excludes 0 and both seeds have the same sign; **G-** when the upper end of the interval is below +0.01; otherwise **G undecided**; the unsnapped read-out of b must not lose more than 0.01 on the pooled mean (reported with its interval; a non-inferiority bound, not a second gain bar). **(R) robustness, arm b read at 30 % wrong counts:** **R+** when the lower end of the interval of (b30 - twin) is at least -0.01; **R-** when its upper end is below 0 (significantly worse); otherwise **R undecided**. **(C) the count itself (attribution):** the interval of (b clean - b U), U = ALL counts unknown with the arm geometry kept (U is read for b only: arm a never saw unknown counts with geometry), excludes 0 and is positive: **C+**, otherwise **C-: the gain, if any, is the arm geometry, not the count.** **Tokens:** G+ with R+ and C+: **KEEP AS AN OPTIONAL INPUT**; G+ with R+ and not C+: **KEEP AS GEOMETRY INPUT (not a count prior)**; G+ with R-: **KEEP ONLY WITH A VERIFIED MAP**; R- with G- or undecided: **HARMFUL (a wrong map costs, the clean map does not pay)**; G- with R+: **TIE (no measurable gain, harmless)**; everything else: **INCONCLUSIVE (underpowered: report the interval, the U / S attribution and the gate norm, no recommendation)**. The kill line is separate. At the card's own prediction (+0.008 clean, -0.003 at 30 %) the likely token is INCONCLUSIVE and that is an honest outcome. The clean row is an UPPER BOUND, not a real-map result: the arm table is built from the GT end clusters (section 1); it must be labelled so in this card and in the report. Reported next to the rule: the table "trained at noise X, read at noise Y" (a, b x clean / 10 % / 30 % / +-1 / U (b) / shuffled), pair recall and precision from the dump, lanes found, junction F1, the gate norm ||sigmoid(g) f|| / ||t|| (and its correlation with the correctness of the count), the gain by arms with count >= 2 (the analysis code is part of the build list).

"""
s = s[:i] + rule + s[j:]
rep("A keypoint with no arm within 6 m is absent (features 0, flag 1).", "A keypoint with no arm within 10 m is absent (features 0, flag 1); **the association and presence radius is 10 m, not 6 m (delta critic B4: `c` is the midpoint of the entry and exit centroids, up to 14 m apart (`jgt.ARM_JOIN_DIST`); 13.0 % of the entry ends and 13.2 % of the exit ends lie more than 6 m from `c`, 5.6 % / 3.2 % more than 8 m, 1.0 % / 0 % more than 10 m)**.")
rep("**U (all counts unknown, geometry kept)**", "**U (ALL counts unknown, geometry kept; read for b only)**")
rep("each arm's count (per direction) is wrong with probability r:", "each arm's count (per direction) is wrong with probability r (the read-outs at 10 % and 30 % add NO unknown arms; the +-1 read-out has rate 0.3: every count moves by +-1 with probability 0.3):")
rep("and 15 % of the arms (in b's training and in the unknown read-out) are marked UNKNOWN (count 0, flag 1: the unknown flag and the absent flag are the SAME channel); the arm centre shifts by up to 2 m and the heading by up to 5 degrees (iid per frame);", "and, in b's TRAINING only, 15 % of the arms are marked UNKNOWN (count 0, flag 1: the unknown flag and the absent flag are the SAME channel) and 20 % of the junctions are 'counts unknown, geometry kept' (so that the U read-out is in distribution for b); the arm centre shifts by up to 2 m and the heading by up to 5 degrees (iid per frame), applied ONLY when r > 0 (b's r = 0 junctions equal the clean read-out); the rate r is computed inside the data path from the zone index (hash of token and zone; arms with zone -1 share one r) and the zone index is not carried by the table;")
rep("**Step 0 result (2026-11-15 11:10,", "**Correction of the step 0 reading (delta critic, 2026-11-15 11:25): the STRICT row (6 m) is partly an artefact of the 6 m radius (13 % of the true ends lie farther from the arm centre): its deficit of 0.30 and its 25 % of missed GT ends are inflated; READ ONLY THE LOOSE ROW (10 m) as the ceiling. Section 1 promised the GT pairs lost behind a deficit and the false pairs behind a surplus: the script counts ENDS and KEYPOINTS, not pairs (not done); 'these are the duplicates that `dup_frac` counts' is an inference, not measured, and a surplus keypoint may also be a true end that the GT lacks.**\n\n**Step 0 result (2026-11-15 11:10,")
rep('"budget_gpu_h": 8.0', '"budget_gpu_h": 8.5')
rep("= about 7.5 slot hours (budget 8)", "= about 7.0 slot hours plus about 1.3 h of dumps (all read-outs of a model in one pass over the loader brings the dumps down) = about 8.3 (budget 8.5)")
rep("the analysis code of the splits, `temp/e291/start_arms.sh`", "the analysis code of the splits, `jdiag.boot_pooled` (new function in the not-frozen `jdiag.py`: asserts identical scene lists of all four counts files, one scene draw per resample for both seeds, the mean over seeds of the topo F1 difference, percentiles of the 1000 pooled values and the two per-seed differences), a hardening assert in the staged `jends_train.py` (`float(os.environ.get('BFLC_SIG', '1.5'))` equal to the sigma stored in the maps checkpoint's args: a missing `BFLC_SIG` in any launcher stops the run), `temp/e291/start_arms.sh`")
i = s.index("**Power (critic finding 4):**")
j = s.index("- **The discussion the numbers feed")
s = s[:i] + "**Power (recomputed after the delta critic):** two seeds of the same recipe differ by 0.0040 (E312 snapped 0.6825 / 0.6864) with a 95 % scene interval [-0.0077, +0.0164] for one pair (half-width about 0.012); pooling two seeds gives about 0.009 (to be measured). A gain of +0.008 therefore cannot show, G+ needs about +0.011 or more; R+ needs the point to be at least about 0.000 to +0.002 at 30 % wrong. The card is a MEASUREMENT read through the pooled interval, the twin and the U / S read-outs: INCONCLUSIVE is the likely token at the stated prediction and it is reported as that, not as a failure.\n" + s[j:]
rep("Status 2026-11-15 10:50: card v3 written, step 0 not run, nothing built; the second critic pass comes after the build brief.", "Status 2026-11-15 11:25: card v4 written (delta critic taken), step 0 run, a coder is building the staged prior; no GPU job yet.")
rep("First pass (version 2) 2026-11-15 10:25: REVISE, 17 findings and the missing step 0, all taken into this version. A second pass is needed on the rule and on the code before any GPU run.", "First pass (version 2) 2026-11-15 10:25: REVISE, 17 findings and the missing step 0, taken into version 3. Delta check of version 3 (2026-11-15 11:20): REVISE, four blocking points (three-valued G / R with INCONCLUSIVE, the twin as the primary control, the clean-minus-U attribution clause, the 10 m radius) and six smaller ones, all taken into this version. A pass on the code before any GPU run.")
io.open(p, "w", encoding="utf-8", newline="").write(s)
print("ok")
